        replay = authority.replayEvents;
        const hashes = [];
        replay((event) => {
          hashes.push(event.hash);
        });
        expect(() => replay(async () => {})).toThrow("synchronous");
        expect(() => replay(() => Promise.resolve())).toThrow("synchronous");
        return hashes;
      },
    }));
    expect(hashes).toEqual(
      store.readVerifiedEvents(id).map((event) => event.hash),
    );
    expect(() => replay(() => {})).toThrow("closed");
    expect(() =>
      store.readVerifiedProjection(id, () => ({
        accept() {},
        finish(authority) {
          let changed = false;
          authority.replayEvents(() => {
            if (changed) return;
            changed = true;
            appendFileSync(
              join(root, "home", "sessions", `${id}.jsonl`),
              "{}\n",
            );
          });
        },
      })),
    ).toThrow();
  });

  it("isolates full-copy forks and reports snapshot branches without borrowing parent content", async () => {
    const id = "history-parent";
    start(id);
    await compact(id, "parent-compact");
    const parent = readSessionTranscriptHistory(id);
    const fork = store.forkSession(id, { requestId: "history-fork" });
    const forkId = typeof fork === "string" ? fork : fork.id;
    store.appendUserMessage(forkId, "fork only");
    const child = readSessionTranscriptHistory(forkId);
    expect(texts(child).slice(0, -1)).toEqual(texts(parent));
    expect(child.messages[0].id).not.toBe(parent.messages[0].id);
    expect(texts(readSessionTranscriptHistory(id))).toEqual(texts(parent));
    expect(() =>
      readSessionTranscriptHistory(forkId, {
        cursor: readSessionTranscriptHistory(id, { limit: 1 }).nextCursor,
      }),
    ).toThrow("invalid transcript history cursor");
    store.createBranchSession({
      branchSessionId: "history-branch",
      parentSessionId: id,
      messages: [{ role: "user", content: "branch snapshot" }],
    });
    const branch = readSessionTranscriptHistory("history-branch");
    expect(texts(branch)).toEqual(["branch snapshot"]);
    expect(branch.coverage.reason).toBe("branch-snapshot");
  });

  it.each(["physical-store-import", "session-end", "unknown"])(
    "treats %s snapshots as replacement boundaries",
    (reason) => {
      const id = `history-${reason}`;
      start(id, 1);
      store.appendCompactEvent(id, {
        reason,
        messages: [{ role: "assistant", content: "saved snapshot" }],
      });
      const page = readSessionTranscriptHistory(id);
      expect(texts(page)).toEqual(["saved snapshot"]);
      expect(page.coverage.reason).toBe("context-snapshot");
    },
  );

  it("falls back to the explicit snapshot when a canonical payload is inconsistent", async () => {
    const id = "history-invalid-compact";
    start(id);
    await compact(id, "valid-compact");
    const valid = store.readVerifiedEvents(id).at(-1).data;
    store.appendCompactEvent(id, {
      ...valid,
      messages: [{ role: "user", content: "replacement" }],
    });
    expect(texts(readSessionTranscriptHistory(id))).toEqual(["replacement"]);
    store.appendCompactEvent(id, {
      ...valid,
      canonical: { ...valid.canonical, digest: "invalid" },
    });
    expect(readSessionTranscriptHistory(id).coverage.reason).toBe(
      "context-snapshot",
    );
  });

  it("reads through the command without modifying authority and rejects a forged tail", async () => {
    const id = "history-command";
    start(id, 2);
    const before = store.readVerifiedEvents(id);
    const program = new Command();
    registerSessionShowSubcommand(program.command("session"), program);
    const output = vi.spyOn(console, "log").mockImplementation(() => {});
    try {
      await program.parseAsync(
        [
          "session",
          "show",
          "--json",
          "--history",
          "--page-size",
          "2",
          "--",
          id,
        ],
        { from: "user" },
      );
      const page = parseTranscriptPage(output.mock.calls.at(-1)[0], id);
      expect(page.messages).toHaveLength(2);
      expect(store.readVerifiedEvents(id)).toEqual(before);
    } finally {
      output.mockRestore();
    }
    appendFileSync(
      join(root, "home", "sessions", `${id}.jsonl`),
      '{"type":"assistant_message","data":{"role":"assistant","content":"forged"}}\n',
    );
    expect(() => readSessionTranscriptHistory(id)).toThrow();
  });

  it("bounds retained bytes and traverses oversized rows without dropping page identities", () => {
    const events = Array.from({ length: 12 }, (_, i) => ({
      type: "assistant_message",
      hash: (i + 1).toString(16).padStart(64, "0"),
      data: { role: "assistant", content: "中".repeat(210000) },
    }));
    let cursor = null;
    const rows = [];
    do {
      const projection = createSessionTranscriptHistoryProjection("large", {
        limit: 100,
        cursor,
      });
      events.forEach((event) => projection.accept(event));
      const page = projection.finish({
        headHash: events.at(-1).hash,
        eventCount: events.length,
      });
      expect(Buffer.byteLength(JSON.stringify(page))).toBeLessThan(
        1024 * 1024 + 4096,
      );
      expect(
        page.messages.every((m) => m.truncated && m.text.length === 200000),
      ).toBe(true);
      rows.unshift(...page.messages);
      cursor = page.nextCursor;
    } while (cursor);
    expect(rows.map((row) => row.ordinal)).toEqual(
      events.map((_, index) => index),
    );
    expect(new Set(rows.map((row) => row.id)).size).toBe(events.length);
  });
});

import { canonicalDigest } from "@chainlesschain/context-memory-kernel";
import { createHash } from "node:crypto";
import { SESSION_GENERATION_AUTHORITY_FIELD } from "../harness/session-list-index.js";
import {
  encodePersistedMessage,
  decodeVerifiedPersistedMessage,
  getDurableSystemMessageProvenance,
  projectCanonicalResumeMessages,
} from "./session-message-provenance.js";

export const BRANCH_HISTORY_SCHEMA = "chainlesschain.session-branch-history/v1";
export const BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA =
  "chainlesschain.session-branch-history/v2";
export const BRANCH_HISTORY_MESSAGE = "session_history_message";
export const BRANCH_HISTORY_ORIGIN = "session_history_origin";
const capabilities = new WeakMap();

export const branchContextDigest = (messages) =>
  canonicalDigest(
    projectCanonicalResumeMessages(messages, { strict: true }).map(
      encodePersistedMessage,
    ),
    "chainlesschain.branch-history-context/v1",
  );
export const branchMessageDigest = (message) =>
  canonicalDigest(message, "chainlesschain.branch-history-message/v1");

// A caller cannot smuggle JSON-shaped history into a new authority chain. The
// capability exists only inside a verified source projection's synchronous lock.
export function withSessionBranchHistory(plan, task) {
  if (typeof task !== "function" || task.constructor?.name === "AsyncFunction")
    throw new TypeError("Branch history consumer must be synchronous");
  const capability = Object.freeze({});
  capabilities.set(capability, plan);
  try {
    const result = task(capability);
    if (result && typeof result.then === "function")
      throw new TypeError("Branch history consumer must be synchronous");
    return result;
  } finally {
    capabilities.delete(capability);
  }
}

export function resolveSessionBranchHistory(
  capability,
  parentSessionId,
  messages,
) {
  if (capability == null) return null;
  const plan = capabilities.get(capability);
  if (
    !plan ||
    plan.parentSessionId !== parentSessionId ||
    plan.contextDigest !== branchContextDigest(messages)
  ) {
    throw new Error(
      "Branch history capability is expired or does not match the branch",
    );
  }
  return plan;
}

export function createBranchHistoryImport() {
  let start = null;
  let index = 0;
  let active = null;
  const hash = (value) =>
    typeof value === "string" && /^[a-f0-9]{64}$/u.test(value);
  const integer = (value) => Number.isSafeInteger(value) && value >= 0;
  const invalid = () => {
    const error = new Error(
      "Branch display history is incomplete or inconsistent",
    );
    error.code = "SESSION_BRANCH_HISTORY_INVALID";
    throw error;
  };
  const require = (condition) => {
    if (!condition) invalid();
  };

  return {
    accept(event) {
      index += 1;
      if (index === 1 && event.type === "session_start") {
        const data = { ...event.data };
        delete data[SESSION_GENERATION_AUTHORITY_FIELD];
        start = { type: event.type, data };
      }
      if (event.type === "session_branch" && event.data?.history != null) {
        const descriptor = event.data.history;
        require(
          index === 2 &&
            start &&
            !active &&
            [
              BRANCH_HISTORY_SCHEMA,
              BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA,
            ].includes(descriptor.schema) &&
            hash(descriptor.sourceGeneration) &&
            integer(descriptor.totalMessages) &&
            integer(descriptor.contextMessageCount) &&
            descriptor.contextMessageCount <= 32768,
        );
        const coverage = descriptor.coverage;
        require(
          coverage?.kind === "from-origin"
            ? coverage.boundaryEvent === null && coverage.reason === null
            : coverage?.kind === "snapshot-boundary" &&
                hash(coverage.boundaryEvent) &&
                [
                  "timeline-replacement",
                  "context-snapshot",
                  "branch-snapshot",
                ].includes(coverage.reason),
        );
        const digest = createHash("sha256").update(
          `[${JSON.stringify(start)},${JSON.stringify({ type: event.type, data: event.data })}`,
        );
        active = {
          descriptor,
          digest,
          rows: 0,
          contexts: 0,
          pending: null,
          textParts: [],
          textBytes: 0,
          textIdentity: null,
          contextStarted: false,
        };
        return { kind: "start", coverage };
      }
      if (!active) {
        if (
          [BRANCH_HISTORY_MESSAGE, BRANCH_HISTORY_ORIGIN].includes(
            event.type,
          ) ||
          (event.type === "session_branch_complete" &&
            event.data?.schemaVersion === 2)
        )
          invalid();
        return null;
      }
      const state = active;
      if (event.type === "session_branch_complete") {
        require(
          !state.pending &&
            state.textParts.length === 0 &&
            state.rows === state.descriptor.totalMessages &&
            state.contexts === state.descriptor.contextMessageCount &&
            event.data?.schemaVersion === 2 &&
            event.data.messageCount === state.contexts &&
            event.data.inputDigest ===
              `sha256:${state.digest.update("]").digest("hex")}`,
        );
        active = null;
        return { kind: "complete" };
      }
      state.digest.update(
        `,${JSON.stringify({ type: event.type, data: event.data })}`,
      );
      if (event.type === BRANCH_HISTORY_MESSAGE) {
        const row = event.data;
        require(
          !state.contextStarted &&
            state.rows < state.descriptor.totalMessages &&
            ["user", "assistant", "tool"].includes(row?.role) &&
            typeof row.text === "string" &&
            row.text.length <= 128 * 1024 &&
            row.part === state.textParts.length &&
            typeof row.last === "boolean" &&
            hash(row.sourceEventId) &&
            integer(row.sourceItemIndex),
        );
        const identity = `${row.role}:${row.sourceEventId}:${row.sourceItemIndex}`;
        require(state.textIdentity === null || state.textIdentity === identity);
        state.textIdentity = identity;
        state.textBytes += Buffer.byteLength(row.text);
        require(
          state.textBytes <= 16 * 1024 * 1024 && state.textParts.length < 256,
        );
        state.textParts.push(row.text);
        if (!row.last) return { kind: "archive-part" };
        const message = { role: row.role, content: state.textParts.join("") };
        state.textParts = [];
        state.textBytes = 0;
        state.textIdentity = null;
        state.rows += 1;
        return { kind: "archive", message };
      }
      if (
        ["user_message", "assistant_message", "system"].includes(event.type)
      ) {
        require(
          !state.pending &&
            state.textParts.length === 0 &&
            state.rows === state.descriptor.totalMessages &&
            state.contexts < state.descriptor.contextMessageCount &&
            event.data?.role ===
              {
                user_message: "user",
                assistant_message: "assistant",
                system: "system",
              }[event.type],
        );
        state.contextStarted = true;
        state.pending = event.data;
        return { kind: "context" };
      }
      if (event.type === BRANCH_HISTORY_ORIGIN) {
        const message = state.pending;
        const origin = event.data?.origin;
        require(
          message && event.data.messageDigest === branchMessageDigest(message),
        );
        require(
          origin === null
            ? message.role === "system"
            : origin &&
                integer(origin.first) &&
                integer(origin.last) &&
                origin.first <= origin.last &&
                origin.last < state.rows &&
                (message.role !== "system" ||
                  (state.descriptor.schema ===
                    BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA &&
                    getDurableSystemMessageProvenance(
                      decodeVerifiedPersistedMessage(message),
                    ))),
        );
        state.contexts += 1;
        state.pending = null;
        return { kind: "origin", message, origin };
      }
      invalid();
    },
    finish() {
      if (active) invalid();
    },
  };
}

