const crypto = require("crypto");
const { compileElicitationSchema } = require("../vendor/elicitation-schema");

function stable(value, depth = 0, budget = { nodes: 0, chars: 0 }) {
  budget.nodes++;
  budget.chars += typeof value === "string" ? value.length : 0;
  if (depth > 20 || budget.nodes > 8192 || budget.chars > 131072)
    throw new Error("Question structure exceeds recovery limits");
  if (Array.isArray(value)) {
    if (value.length > 8192) throw new Error("Question has too many values");
    return value.map((v) => stable(v, depth + 1, budget));
  }
  if (value && typeof value === "object") {
    const keys = Object.keys(value);
    if (keys.length > 8192) throw new Error("Question has too many fields");
    return Object.fromEntries(
      keys.sort().map((key) => {
        budget.chars += key.length;
        return [key, stable(value[key], depth + 1, budget)];
      }),
    );
  }
  return value;
}

function questionIdentity(sessionId, request) {
  const source = JSON.stringify(
    stable({
      sessionId,
      id: request.id,
      binding: request.binding || null,
      question: request.question,
      options: request.options || null,
      multiSelect: !!request.multiSelect,
      mode: request.mode || request.metadata?.mode || null,
      // App Server keeps blocking/deferred mode separately from MCP form/url.
      // A changed presentation or sensitivity must replace the original review.
      elicitationMode: request.metadata?.mode,
      password: request.password === true ? true : undefined,
      blocking: request.blocking !== false,
      purpose: request.purpose || null,
      contextRevision:
        request.contextRevision ?? request.context_revision ?? null,
      elicitation:
        request.elicitation === true ||
        request.metadata?.kind === "mcp_elicitation",
      schema:
        request.requestedSchema || request.metadata?.requestedSchema || null,
      server: request.server || request.metadata?.server || null,
      url: request.url || request.metadata?.url || null,
      elicitationId:
        request.elicitationId || request.metadata?.elicitationId || null,
    }),
  );
  if (Buffer.byteLength(source) > 128 * 1024)
    throw new Error("Question is too large for draft recovery");
  return crypto.createHash("sha256").update(source).digest("hex");
}

function questionFields(request) {
  if (request.mode === "url" || request.metadata?.mode === "url") return [];
  const schema = request.requestedSchema || request.metadata?.requestedSchema;
  if (schema) {
    const model = compileElicitationSchema(schema);
    if (model.supported)
      return model.fields.flatMap((f) => {
        const base = {
          key: JSON.stringify([f.name]),
          label: f.title || f.name,
        };
        const secret =
          schema.properties?.[f.name]?.writeOnly === true ||
          schema.properties?.[f.name]?.format === "password" ||
          f.inputType === "password";
        if (f.kind === "multi-select")
          return f.options.map((o) => ({
            key: JSON.stringify([f.name, o.value]),
            label: `${base.label}: ${o.label}`,
            kind: secret ? "password" : "checkbox",
            option: true,
          }));
        if (secret) return [{ ...base, kind: "password" }];
        if (f.kind === "boolean") return [{ ...base, kind: "checkbox" }];
        if (f.kind === "single-select")
          return [
            {
              ...base,
              kind: "select",
              choices: f.options.map((o) => String(o.value)),
            },
          ];
        return [
          { ...base, kind: f.inputType === "password" ? "password" : "text" },
        ];
      });
    // Unknown schemas can contain secrets that the host cannot classify. Keep
    // their JSON fallback editable but do not persist it as ordinary text.
    return [{ key: "answer-json", label: "Answer", kind: "password" }];
  }
  if (request.options?.length)
    return request.multiSelect
      ? request.options.map((o, i) => ({
          key: `option-${i}`,
          label: typeof o === "string" ? o : String(o.label ?? o.value ?? ""),
          kind: "checkbox",
          option: true,
        }))
      : [];
  return [{ key: "answer", label: "Answer", kind: "text" }];
}

function normalizeQuestionFields(descriptors, values) {
  if (!Array.isArray(values) || values.length > 128 || descriptors.length > 128)
    throw new Error("Question draft has too many fields");
  const allowed = new Map(
    descriptors.filter((d) => d.kind !== "password").map((d) => [d.key, d]),
  );
  const result = [];
  const seen = new Set();
  let bytes = 0;
  for (const candidate of values) {
    const field = allowed.get(candidate?.key);
    if (!field || seen.has(field.key)) continue;
    seen.add(field.key);
    const value = candidate.value;
    if (
      field.kind === "checkbox"
        ? typeof value !== "boolean"
        : typeof value !== "string"
    )
      throw new Error("Invalid question draft field");
    if (typeof value === "string" && value.length > 32768)
      throw new Error("Question draft field exceeds 32K characters");
    if (
      field.kind === "select" &&
      value !== "" &&
      !field.choices.includes(value)
    )
      throw new Error("Question draft choice is no longer available");
    bytes += Buffer.byteLength(JSON.stringify({ key: field.key, value }));
    if (bytes > 65536) throw new Error("Question draft exceeds 64 KiB");
    result.push({ key: field.key, value });
  }
  return result;
}

function questionDraftText(descriptors, fields) {
  const values = new Map(fields.map((f) => [f.key, f.value]));
  return descriptors
    .filter(
      (d) =>
        d.kind !== "password" &&
        values.has(d.key) &&
        values.get(d.key) !== "" &&
        (!d.option || values.get(d.key)),
    )
    .map((d) => `${d.label}: ${values.get(d.key)}`)
    .join("\n")
    .slice(0, 65536);
}

module.exports = {
  questionIdentity,
  questionFields,
  normalizeQuestionFields,
  questionDraftText,
};

import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs/promises";
import path from "node:path";
import { tmpdir } from "node:os";
import { randomUUID } from "node:crypto";
import { Window } from "happy-dom";
import { DraftStore } from "../../../vscode-extension/src/chat/draft-store.js";
import { QuestionDrafts } from "../../../vscode-extension/src/chat/question-drafts.js";
import {
  questionIdentity,
  questionFields,
  normalizeQuestionFields,
} from "../../../vscode-extension/src/chat/question-draft-contract.js";
import { ChatViewProvider } from "../../../vscode-extension/src/chat/chat-view.js";
import { buildChatHtml } from "../../../vscode-extension/src/chat/chat-html.js";

const cleanups = [];
afterEach(async () => {
  for (const fn of cleanups.splice(0).reverse()) await fn();
});
async function storage() {
  const root = await fs.mkdtemp(path.join(tmpdir(), "cc-question-"));
  cleanups.push(() => fs.rm(root, { recursive: true, force: true }));
  return root;
}
const binding = {
  backgroundAgentId: null,
  sessionId: "session-1",
  turnId: "turn-1",
  toolUseId: "tool-1",
  sequence: 1,
};
const request = {
  kind: "question",
  id: "q1",
  question: "Choose a target",
  binding,
};
const values = [{ key: "answer", value: "half entered 中文" }];
const payload = (q, extra = {}) => ({
  ...q,
  fields: values,
  revision: 1,
  ...extra,
});
function controller(store, overrides = {}) {
  cleanups.push(async () => {
    let queue;
    do {
      queue = store.queue;
      await queue;
    } while (queue !== store.queue);
  });
  const conv = {
    id: "a",
    sessionId: "session-1",
    draftKey: randomUUID(),
    _sessionToken: {},
    session: { running: true, sendEvent: vi.fn(() => true) },
    ...overrides,
  };
  const messages = [];
  const drafts = new QuestionDrafts({
    store,
    getConversation: (id) => (id === conv.id ? conv : null),
    post: (m) => messages.push(m),
    refresh: () => {},
  });
  return { drafts, conv, messages };
}
function ui(backup = {}) {
  const window = new Window({
    settings: {
      enableJavaScriptEvaluation: true,
      disableCSSFileLoading: true,
      disableJavaScriptFileLoading: true,
    },
  });
  cleanups.push(() => window.happyDOM.abort());
  const sent = [];
  let state = backup;
  window.acquireVsCodeApi = () => ({
    postMessage: (m) => sent.push(m),
    getState: () => state,
    setState: (v) => {
      state = v;
    },
  });
  window.document.write(
    buildChatHtml({ nonce: "n", cspSource: "vscode-resource:" }),
  );
  const emit = (data) =>
    window.dispatchEvent(new window.MessageEvent("message", { data }));
  const card = (q) => window.document.getElementById("q-" + q.questionInstance);
  return { window, sent, emit, card, state: () => state };
}

describe("question recovery authority and persistence", () => {
  it("recovers an unfinished bound question in a fresh host without sending an answer", async () => {
    const root = await storage();
    const first = controller(new DraftStore(root));
    const q = first.drafts.register(first.conv, request);
    await first.drafts.save(payload(q));
    const next = controller(new DraftStore(root), {
      draftKey: first.conv.draftKey,
    });
    const restored = next.drafts.register(next.conv, request);
    expect(restored.questionInstance).not.toBe(q.questionInstance);
    await next.drafts.restore(restored);
    expect(next.messages.at(-1)).toMatchObject({
      kind: "questionDraftSnapshot",
      fields: values,
      state: "draft",
    });
    expect(next.conv.session.sendEvent).not.toHaveBeenCalled();
    await next.drafts.save(
      payload(restored, { fields: [{ key: "answer", value: "finished" }] }),
    );
    expect(
      (await next.drafts.store.view(first.conv.draftKey)).questions,
    ).toHaveLength(1);
  });

  it("archives cancellations, schema changes and late edits without reviving the request", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    await h.drafts.save(payload(q));
    const changed = h.drafts.register(h.conv, {
      ...request,
      options: ["a", "b"],
    });
    await h.drafts.save(
      payload(q, { fields: [{ key: "answer", value: "late text" }] }),
    );
    await h.drafts.answer(payload(q, { answer: "stale" }));
    await h.drafts.restore(changed);
    expect(h.messages.at(-1).fields).toEqual([]);
    expect(h.conv.session.sendEvent).not.toHaveBeenCalled();
    expect(
      (await h.drafts.store.view(h.conv.draftKey)).questions[0],
    ).toMatchObject({ status: "archived", text: "Answer: late text" });
  });

  it("does not restore unbound or already submitted answers as a new live form", async () => {
    const root = await storage();
    for (const bound of [false, true]) {
      const h = controller(new DraftStore(root));
      const original = { ...request, binding: bound ? binding : undefined };
      const q = h.drafts.register(h.conv, original);
      await h.drafts.save(payload(q));
      if (bound) await h.drafts.answer(payload(q, { answer: "sent" }));
      const next = controller(new DraftStore(root), {
        draftKey: h.conv.draftKey,
      });
      const nextQ = next.drafts.register(next.conv, original);
      await next.drafts.restore(nextQ);
      expect(next.messages.at(-1).fields).toEqual([]);
      expect(
        (await next.drafts.store.view(h.conv.draftKey)).questions[0].text,
      ).toContain("half entered");
      expect(next.conv.session.sendEvent).not.toHaveBeenCalled();
    }
  });

  it("reserves one response, persists before writing, and leaves failed delivery unknown", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    h.conv.session.sendEvent.mockReturnValue(false);
    await Promise.all([
      h.drafts.answer(payload(q, { answer: "x" })),
      h.drafts.answer(payload(q, { answer: "x" })),
    ]);
    expect(h.conv.session.sendEvent).toHaveBeenCalledOnce();
    expect(h.messages.at(-1)).toMatchObject({ state: "unknown" });
    expect(
      (await h.drafts.store.view(h.conv.draftKey)).questions[0].status,
    ).toBe("archived");
    await h.drafts.answer(payload(q, { answer: "retry" }));
    expect(h.conv.session.sendEvent).toHaveBeenCalledOnce();
  });

  it("does not dispatch on storage failure or a reset during the save", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    await h.drafts.restore(q);
    const save = vi
      .spyOn(h.drafts.store, "saveQuestion")
      .mockRejectedValueOnce(new Error("disk full"));
    await h.drafts.answer(payload(q, { answer: "x" }));
    expect(h.messages.at(-1)).toMatchObject({
      state: "draft",
      text: "Answer was not sent: disk full",
    });
    save.mockRestore();
    let release;
    const original = h.drafts.store.saveQuestion.bind(h.drafts.store);
    vi.spyOn(h.drafts.store, "saveQuestion").mockImplementation(
      async (...args) => {
        await new Promise((resolve) => {
          release = resolve;
        });
        return original(...args);
      },
    );
    const sending = h.drafts.answer(payload(q, { answer: "x" }));
    await vi.waitFor(() => expect(release).toBeTypeOf("function"));
    h.conv._sessionToken = {};
    release();
    await sending;
    expect(h.conv.session.sendEvent).not.toHaveBeenCalled();
  });

  it("keeps deferred questions across turn end and bounds stored questions", async () => {
    const h = controller(new DraftStore(await storage()));
    const blocking = h.drafts.register(h.conv, request);
    const deferred = h.drafts.register(h.conv, {
      ...request,
      id: "later",
      blocking: false,
    });
    await h.drafts.save(payload(blocking));
    await h.drafts.save(payload(deferred));
    h.drafts.archiveConversation(h.conv, { blockingOnly: true });
    expect(h.drafts.match(deferred).state).toBe("draft");
    expect(h.drafts.match(blocking).state).toBe("archived");
    for (let i = 2; i < 16; i++)
      await h.drafts.save(
        payload(h.drafts.register(h.conv, { ...request, id: "q" + i })),
      );
    await expect(
      h.drafts.save(
        payload(h.drafts.register(h.conv, { ...request, id: "overflow" })),
      ),
    ).rejects.toThrow("16 questions");
    expect((await h.drafts.store.list())[0].label).toBe(request.question);
  });
});

describe("generated question forms", () => {
