  it("keeps a rejected response unresolved and exposes archived text without sending it", async () => {
    const h = await host();
    await h.provider._handleMessage(
      payload(h.q, { type: "answer", fields: [], answer: null }),
    );
    h.provider._makeOnEvent(
      h.a.id,
      h.a._sessionToken,
    )({
      type: "question_response_rejected",
      id: h.q.id,
      reason: "persistence_failed",
    });
    expect(
      h.messages.filter((m) => m.kind === "questionState").at(-1),
    ).toMatchObject({ state: "unknown" });
    const saved = (await h.provider._draftStore.view(h.a.draftKey))
      .questions[0];
    const before = h.a.session.sendEvent.mock.calls.length;
    await h.provider._handleMessage({
      type: "questionDraftCopy",
      convId: h.a.id,
      draftKey: h.a.draftKey,
      questionId: saved.id,
    });
    expect(h.messages.at(-1)).toMatchObject({
      kind: "draftCopy",
      composer: { text: "", images: [] },
    });
    expect(h.a.session.sendEvent.mock.calls.length).toBe(before);
  });

  it("routes an asynchronous URL answer to its original session after tab switching", async () => {
    const h = await host();
    let finish;
    h.provider.vscode.env.openExternal.mockImplementation(
      () =>
        new Promise((resolve) => {
          finish = resolve;
        }),
    );
    const sending = h.provider._handleMessage(
      payload(h.q, {
        type: "openElicitationUrl",
        fields: [],
        url: "https://attacker.test/",
      }),
    );
    await vi.waitFor(() => expect(finish).toBeTypeOf("function"));
    expect(h.provider.vscode.env.openExternal).toHaveBeenCalledWith(
      "https://example.test/",
    );
    h.provider._openNewTab();
    const b = h.provider._activeConv();
    b.session = { running: true, sendEvent: vi.fn(), stop() {} };
    finish(true);
    await sending;
    expect(b.session.sendEvent).not.toHaveBeenCalled();
    expect(h.a.session.sendEvent).toHaveBeenCalledWith({
      type: "answer",
      id: "url",
      answer: {},
      binding,
    });
  });

  it("ignores callbacks after the owning session is stopped and replacement requests appear", async () => {
    const h = await host();
    let finish;
    const old = h.a.session;
    h.provider.vscode.env.openExternal.mockImplementation(
      () =>
        new Promise((resolve) => {
          finish = resolve;
        }),
    );
    const sending = h.provider._handleMessage(
      payload(h.q, { type: "openElicitationUrl", fields: [] }),
    );
    await vi.waitFor(() => expect(finish).toBeTypeOf("function"));
    h.provider._stopSession(h.a);
    const replacement = { running: true, sendEvent: vi.fn(), stop() {} };
    h.a.session = replacement;
    finish(true);
    await sending;
    expect(old.sendEvent).not.toHaveBeenCalled();
    expect(replacement.sendEvent).not.toHaveBeenCalled();
    await h.provider._handleMessage(
      payload(h.q, { type: "answer", answer: "stale" }),
    );
    expect(replacement.sendEvent).not.toHaveBeenCalled();
  });
});

/**
 * Vendor the shared MCP elicitation schema into the VS Code extension.
 *
 * VSCE packages only packages/vscode-extension, so a runtime reference to the
 * sibling packages/elicitation-schema directory works in the monorepo but is
 * absent after installing the VSIX. Keep an exact, tracked copy under src/
 * and verify it before every package build.
 *
 * Usage:
 *   node scripts/sync-elicitation-schema.mjs
 *   node scripts/sync-elicitation-schema.mjs --check
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const extensionRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const sourceRoot = join(extensionRoot, "..", "elicitation-schema");
const sourcePath = join(sourceRoot, "index.js");
const sourcePackagePath = join(sourceRoot, "package.json");
const targetRoot = join(extensionRoot, "src", "vendor", "elicitation-schema");
const targetPath = join(targetRoot, "index.js");
const metadataPath = join(targetRoot, "VENDORED.md");

if (!existsSync(sourcePath) || !existsSync(sourcePackagePath)) {
  console.error(
    "packages/elicitation-schema is missing next to packages/vscode-extension",
  );
  process.exit(1);
}

const source = readFileSync(sourcePath);
const sourcePackage = JSON.parse(readFileSync(sourcePackagePath, "utf8"));
const metadata = Buffer.from(
  `# Vendored ${sourcePackage.name} v${sourcePackage.version}\n\n` +
    "Generated by scripts/sync-elicitation-schema.mjs — DO NOT EDIT.\n" +
    "Source: packages/elicitation-schema/index.js. Edit there and re-sync.\n",
  "utf8",
);

if (process.argv.includes("--check")) {
  const checks = [
    [targetPath, source],
    [metadataPath, metadata],
  ];
  for (const [file, expected] of checks) {
    if (!existsSync(file) || !readFileSync(file).equals(expected)) {
      console.error(
        `Vendored elicitation schema is stale or missing: ${file}\n` +
          "Run `node scripts/sync-elicitation-schema.mjs` and commit the result.",
      );
      process.exit(1);
    }
  }
  console.log(
    `vendored ${sourcePackage.name} v${sourcePackage.version} is current`,
  );
  process.exit(0);
}

mkdirSync(targetRoot, { recursive: true });
writeFileSync(targetPath, source);
writeFileSync(metadataPath, metadata);
console.log(
  `vendored ${sourcePackage.name} v${sourcePackage.version} -> ${targetRoot}`,
);

/**
 * Shared MCP form-elicitation schema core.
 *
 * This deliberately implements the restricted, flat vocabulary accepted by
 * MCP form elicitation. It is not a general JSON Schema implementation:
 * nested objects/arbitrary arrays, $ref, and the Draft 2020-12 meta-vocabulary
 * are outside this package's contract.
 *
 * The UMD wrapper lets Desktop/Node require the exact same executable module
 * that VS Code embeds in its CSP-isolated Webview.
 */
(function attachElicitationSchema(root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) {
    module.exports = api;
  }
  if (root) {
    root.CcElicitationSchema = api;
  }
})(
  typeof globalThis !== "undefined" ? globalThis : this,
  function createElicitationSchemaApi() {
    "use strict";

    const VOCABULARY_VERSION = "mcp-restricted-form-v1";
    const STRING_FORMATS = new Set(["email", "uri", "date", "date-time"]);

    function isRecord(value) {
      return (
        value !== null && typeof value === "object" && !Array.isArray(value)
      );
    }

    function hasOwn(value, key) {
      return Object.prototype.hasOwnProperty.call(value, key);
    }

    function cloneJsonValue(value) {
      if (Array.isArray(value)) {
        return value.map(cloneJsonValue);
      }
      if (isRecord(value)) {
        const copy = {};
        for (const [key, child] of Object.entries(value)) {
          copy[key] = cloneJsonValue(child);
        }
        return copy;
      }
      return value;
    }

    function issue(path, code, message) {
      return { path, code, message };
    }

    function finiteNumber(value) {
      return typeof value === "number" && Number.isFinite(value);
    }

    function nonNegativeInteger(value) {
      return Number.isInteger(value) && value >= 0;
    }

    function titledOptions(entries, path, errors) {
      if (!Array.isArray(entries) || entries.length === 0) {
        errors.push(
          issue(path, "invalid_options", "at least one option is required"),
        );
        return [];
      }
      const options = [];
      entries.forEach((entry, index) => {
        const optionPath = `${path}/${index}`;
        if (
          !isRecord(entry) ||
          typeof entry.const !== "string" ||
          typeof entry.title !== "string"
        ) {
          errors.push(
            issue(
              optionPath,
              "invalid_option",
              "titled options require string const and title values",
            ),
          );
          return;
        }
        options.push({ value: entry.const, label: entry.title });
      });
      return options;
    }

    function enumOptions(values, names, path, errors) {
      if (
        !Array.isArray(values) ||
        values.length === 0 ||
        values.some((value) => typeof value !== "string")
      ) {
        errors.push(
          issue(path, "invalid_enum", "enum must contain one or more strings"),
        );
        return [];
      }
      const labels =
        Array.isArray(names) && names.every((name) => typeof name === "string")
          ? names
          : [];
      return values.map((value, index) => ({
        value,
        label: labels[index] === undefined ? value : labels[index],
      }));
    }

    function validateRange(
      spec,
      minimumKey,
      maximumKey,
      integerOnly,
      path,
      errors,
    ) {
      const minimum = spec[minimumKey];
      const maximum = spec[maximumKey];
      if (
        minimum !== undefined &&
        !(integerOnly ? nonNegativeInteger(minimum) : finiteNumber(minimum))
      ) {
        errors.push(
          issue(
            `${path}/${minimumKey}`,
            "invalid_constraint",
            `${minimumKey} must be ${integerOnly ? "a non-negative integer" : "a finite number"}`,
          ),
        );
      }
      if (
        maximum !== undefined &&
        !(integerOnly ? nonNegativeInteger(maximum) : finiteNumber(maximum))
      ) {
        errors.push(
          issue(
            `${path}/${maximumKey}`,
            "invalid_constraint",
            `${maximumKey} must be ${integerOnly ? "a non-negative integer" : "a finite number"}`,
          ),
        );
      }
      if (
        typeof minimum === "number" &&
        typeof maximum === "number" &&
        minimum > maximum
      ) {
        errors.push(
          issue(
            path,
            "invalid_range",
            `${minimumKey} cannot exceed ${maximumKey}`,
          ),
        );
      }
    }

    function normalizeField(name, spec, required, path, errors) {
      if (!isRecord(spec)) {
        errors.push(
          issue(path, "invalid_field_schema", "field schema must be an object"),
        );
        return null;
      }

      const type = spec.type;
      const common = {
        name,
        type,
        title: typeof spec.title === "string" ? spec.title : name,
        description:
          typeof spec.description === "string" ? spec.description : "",
        required,
        hasDefault: hasOwn(spec, "default"),
        default: hasOwn(spec, "default")
          ? cloneJsonValue(spec.default)
          : undefined,
      };

      if (type === "string" && Array.isArray(spec.enum)) {
        return {
          ...common,
          kind: "single-select",
          options: enumOptions(
            spec.enum,
            spec.enumNames,
            `${path}/enum`,
            errors,
          ),
        };
      }

      if (type === "string" && Array.isArray(spec.oneOf)) {
        return {
          ...common,
          kind: "single-select",
          options: titledOptions(spec.oneOf, `${path}/oneOf`, errors),
        };
      }

      if (type === "array") {
        if (!isRecord(spec.items)) {
          errors.push(
            issue(
              `${path}/items`,
              "unsupported_array",
              "multi-select arrays require an items schema",
            ),
          );
          return null;
        }
        let options = [];
        if (Array.isArray(spec.items.enum)) {
          options = enumOptions(
            spec.items.enum,
            null,
            `${path}/items/enum`,
            errors,
          );
        } else if (Array.isArray(spec.items.anyOf)) {
          options = titledOptions(
            spec.items.anyOf,
            `${path}/items/anyOf`,
            errors,
          );
        } else {
          errors.push(
            issue(
              `${path}/items`,
              "unsupported_array",
              "only MCP string multi-select arrays are supported",
            ),
          );
        }
        validateRange(spec, "minItems", "maxItems", true, path, errors);
        return {
          ...common,
          kind: "multi-select",
          options,
          minItems: spec.minItems,
          maxItems: spec.maxItems,
        };
      }

      if (type === "boolean") {
        return { ...common, kind: "boolean" };
      }

      if (type === "string") {
        validateRange(spec, "minLength", "maxLength", true, path, errors);
        if (spec.format !== undefined && !STRING_FORMATS.has(spec.format)) {
          errors.push(
            issue(
              `${path}/format`,
              "unsupported_format",
              `unsupported MCP string format: ${String(spec.format)}`,
            ),
          );
        }
        return {
          ...common,
          kind: "text",
          format: STRING_FORMATS.has(spec.format) ? spec.format : null,
          inputType:
            spec.format === "email"
              ? "email"
              : spec.format === "uri"
                ? "url"
                : spec.format === "date"
                  ? "date"
                  : "text",
          minLength: spec.minLength,
          maxLength: spec.maxLength,
        };
      }

      if (type === "number" || type === "integer") {
        validateRange(spec, "minimum", "maximum", false, path, errors);
        return {
          ...common,
          kind: type,
          minimum: spec.minimum,
          maximum: spec.maximum,
          step: type === "integer" ? 1 : "any",
        };
      }

      errors.push(
        issue(
          `${path}/type`,
          "unsupported_type",
          `unsupported MCP elicitation field type: ${String(type)}`,
        ),
      );
      return null;
    }

    function compileElicitationSchema(schema) {
      const errors = [];
      if (!isRecord(schema)) {
        return {
          version: VOCABULARY_VERSION,
          supported: false,
          fields: [],
          required: [],
          errors: [
            issue("", "invalid_schema", "requestedSchema must be an object"),
          ],
        };
      }
      if (schema.type !== "object") {
        errors.push(
          issue(
            "/type",
            "unsupported_root",
            'MCP form requestedSchema must have type "object"',
          ),
        );
      }
      if (!isRecord(schema.properties)) {
        errors.push(
          issue(
            "/properties",
            "invalid_properties",
            "requestedSchema.properties must be an object",
          ),
        );
      }

      const propertyNames = isRecord(schema.properties)
        ? Object.keys(schema.properties)
        : [];
      const required = [];
      if (schema.required !== undefined) {
        if (
          !Array.isArray(schema.required) ||
          schema.required.some((name) => typeof name !== "string")
        ) {
          errors.push(
            issue(
              "/required",
              "invalid_required",
              "required must be an array of property names",
            ),
          );
        } else {
          for (const name of schema.required) {
            if (!propertyNames.includes(name)) {
              errors.push(
                issue(
                  "/required",
                  "unknown_required",
                  `required property is not declared: ${name}`,
                ),
              );
            } else if (!required.includes(name)) {
              required.push(name);
            }
          }
        }
      }

      const fields = [];
      if (isRecord(schema.properties)) {
        for (const [name, spec] of Object.entries(schema.properties)) {
          const field = normalizeField(
            name,
            spec,
            required.includes(name),
            `/properties/${name}`,
            errors,
          );
          if (field) {
            fields.push(field);
          }
        }
      }

      const model = {
        version: VOCABULARY_VERSION,
        supported: errors.length === 0,
        fields,
        required,
        errors,
      };

      if (model.supported) {
        for (const field of fields) {
          if (!field.hasDefault) continue;
          const defaultResult = validateField(field, field.default);
          if (defaultResult) {
            model.errors.push(
              issue(
                `/properties/${field.name}/default`,
                "invalid_default",
                defaultResult.message,
              ),
            );
          }
        }
        model.supported = model.errors.length === 0;
      }
      return model;
    }

