import { isAbortError } from "./abort-utils.js";

export function isEvolutionIngressFailure(error) {
  const visited = new Set();
  for (let current = error; current; current = current.cause) {
    if (visited.has(current) || visited.size >= 32) return true;
    visited.add(current);
    if (current.code === "CC_AGENT_EVOLUTION_INGRESS_FAILED") return true;
  }
  return false;
}

// Admission failures are not provider outages, even when their causes contain
// HTTP status codes or retryable/authentication words.
export function isTerminalModelFailure(error) {
  const visited = new Set();
  for (let current = error; current; current = current.cause) {
    if (visited.has(current) || visited.size >= 32) return true;
    visited.add(current);
    if (
      current.code === "CC_AGENT_EVOLUTION_INGRESS_FAILED" ||
      current.runtimeLedgerPersistence === true ||
      current.workflowEffectOutcomeUnknown === true ||
      /^(?:CC|ERR)_SESSION_BUDGET_/u.test(current.code || "") ||
      isAbortError(current)
    ) {
      return true;
    }
  }
  return false;
}

/**
 * Unit tests for --fallback-model. The base chatFn is injected so no real
 * provider is contacted; only the retry/skip logic is exercised.
 */

import { describe, it, expect, vi } from "vitest";
import {
  isRetryableModelError,
  isModelNotFoundError,
  normalizeFallbackModels,
  makeFallbackChatFn,
  parseFallbackEntry,
  resolveFallbackTarget,
} from "../../src/runtime/fallback-model.js";
import { resolveFallbackModels } from "../../src/commands/agent.js";

describe("isRetryableModelError", () => {
  it("is true for overload / rate-limit / transient status codes", () => {
    expect(isRetryableModelError({ status: 429 })).toBe(true);
    expect(isRetryableModelError({ status: 503 })).toBe(true);
    expect(isRetryableModelError({ statusCode: 529 })).toBe(true);
    expect(isRetryableModelError(new Error("Model is overloaded"))).toBe(true);
    expect(isRetryableModelError(new Error("429 Too Many Requests"))).toBe(
      true,
    );
    expect(isRetryableModelError(new Error("fetch failed"))).toBe(true);
    expect(isRetryableModelError({ code: "ECONNREFUSED" })).toBe(true);
  });

  it("unwraps a retryable cause", () => {
    const err = new Error("request failed");
    err.cause = { code: "ETIMEDOUT" };
    expect(isRetryableModelError(err)).toBe(true);
  });

  it("is false for non-transient errors and nullish input", () => {
    expect(isRetryableModelError(null)).toBe(false);
    expect(isRetryableModelError(new Error("invalid prompt"))).toBe(false);
    expect(isRetryableModelError({ status: 400 })).toBe(false);
    expect(isRetryableModelError({ status: 401 })).toBe(false);
  });
});

describe("makeFallbackChatFn", () => {
  it.each([
    ["projection", { code: "CC_AGENT_EVOLUTION_INGRESS_FAILED" }],
    ["ledger", { runtimeLedgerPersistence: true }],
    ["workflow", { workflowEffectOutcomeUnknown: true }],
    ["budget", { code: "ERR_SESSION_BUDGET_IN_FLIGHT_LIMIT" }],
    ["abort", { name: "AbortError" }],
  ])(
    "never retries a nested %s failure even with permissive predicates",
    async (_label, marker) => {
      const terminal = Object.assign(
        new Error("timeout: model not found"),
        marker,
      );
      const error = Object.assign(
        new Error("provider 503", { cause: terminal }),
        {
          status: 503,
        },
      );
      expect(isRetryableModelError(error)).toBe(false);
      expect(isModelNotFoundError({ status: 404, cause: terminal })).toBe(
        false,
      );
      for (const afterFallback of [false, true]) {
        const baseChatFn = vi.fn().mockRejectedValue(error);
        if (afterFallback)
          baseChatFn.mockRejectedValueOnce(new Error("overloaded"));
        const onFallback = vi.fn();
        const fn = makeFallbackChatFn({
          fallbackModels: ["backup", "third"],
          baseChatFn,
          onFallback,
          isRetryable: () => true,
          isModelNotFound: () => true,
        });
        await expect(fn([], { model: "primary" })).rejects.toBe(error);
        expect(baseChatFn).toHaveBeenCalledTimes(afterFallback ? 2 : 1);
        expect(onFallback).toHaveBeenCalledTimes(afterFallback ? 1 : 0);
      }
    },
  );

  it("fails closed on cyclic error causes", async () => {
    const error = new Error("timeout");
    error.cause = error;
    const baseChatFn = vi.fn().mockRejectedValue(error);
    await expect(
      makeFallbackChatFn({ baseChatFn, fallbackModel: "backup" })([], {}),
    ).rejects.toBe(error);
    expect(baseChatFn).toHaveBeenCalledOnce();
  });

  it.each(["workflowEffectId", "providerRequestId"])(
    "does not hide another attempt under one %s",
    async (field) => {
      const error = new Error("503");
      const baseChatFn = vi.fn().mockRejectedValue(error);
      const fn = makeFallbackChatFn({ baseChatFn, fallbackModel: "backup" });
      await expect(
        fn([], { model: "primary", [field]: "effect:1" }),
      ).rejects.toBe(error);
      expect(baseChatFn).toHaveBeenCalledOnce();
    },
  );

  it.each(["before-primary", "before-backup"])(
    "honors cancellation %s even when it contains a retryable message",
    async (when) => {
      const controller = new AbortController();
      const cancelled = new Error("timeout");
      const baseChatFn = vi.fn().mockRejectedValue(new Error("503"));
      const onFallback = () => controller.abort(cancelled);
      const fn = makeFallbackChatFn({
        baseChatFn,
        fallbackModel: "backup",
        onFallback,
      });
      if (when === "before-primary") controller.abort(cancelled);
      await expect(
        fn([], { model: "primary", signal: controller.signal }),
      ).rejects.toBe(cancelled);
      expect(baseChatFn).toHaveBeenCalledTimes(
        when === "before-primary" ? 0 : 1,
      );
    },
  );

  it("captures strict accounting before the caller mutates options", async () => {
    const options = { model: "primary", strictUsageTelemetry: true };
    const error = new Error("503");
    const baseChatFn = vi.fn(async () => {
      options.strictUsageTelemetry = false;
      throw error;
    });
    await expect(
      makeFallbackChatFn({ baseChatFn, fallbackModel: "backup" })([], options),
    ).rejects.toBe(error);
    expect(baseChatFn).toHaveBeenCalledOnce();
  });

  it("passes through on success without invoking fallback", async () => {
    const baseChatFn = vi.fn(async () => ({ message: { content: "ok" } }));
    const onFallback = vi.fn();
    const fn = makeFallbackChatFn({
      fallbackModel: "backup",
      baseChatFn,
      onFallback,
    });
    const r = await fn([{ role: "user", content: "hi" }], { model: "primary" });
    expect(r.message.content).toBe("ok");
    expect(baseChatFn).toHaveBeenCalledTimes(1);
    expect(onFallback).not.toHaveBeenCalled();
  });

  it("retries with the fallback model on a retryable error", async () => {
    const baseChatFn = vi
      .fn()
      .mockRejectedValueOnce(new Error("overloaded"))
      .mockResolvedValueOnce({ message: { content: "from-backup" } });
    const onFallback = vi.fn();
    const fn = makeFallbackChatFn({
      fallbackModel: "backup",
      baseChatFn,
      onFallback,
    });

    const r = await fn([], { model: "primary", provider: "ollama" });

    expect(r.message.content).toBe("from-backup");
    expect(baseChatFn).toHaveBeenCalledTimes(2);
    // second call keeps provider but swaps model
    expect(baseChatFn.mock.calls[1][1]).toMatchObject({
      model: "backup",
      provider: "ollama",
    });
    expect(onFallback).toHaveBeenCalledWith({
      from: "primary",
      to: "backup",
      crossProvider: false,
      error: "overloaded",
    });
  });

  it("does not issue or announce fallbacks for a strict usage ledger", async () => {
    const primaryError = new Error("overloaded");
    const baseChatFn = vi
      .fn()
      .mockRejectedValueOnce(primaryError)
      .mockResolvedValueOnce({ message: { content: "must-not-run" } });
    const onFallback = vi.fn();
    const fn = makeFallbackChatFn({
      fallbackModels: ["backup-1", "backup-2"],
      baseChatFn,
      onFallback,
    });

    await expect(
      fn([], {
        model: "primary",
        provider: "ollama",
        strictUsageTelemetry: true,
      }),
    ).rejects.toBe(primaryError);

    expect(baseChatFn).toHaveBeenCalledTimes(1);
    expect(onFallback).not.toHaveBeenCalled();
  });

  it("does not retry a non-retryable error", async () => {
    const baseChatFn = vi.fn().mockRejectedValue(new Error("invalid prompt"));
    const fn = makeFallbackChatFn({ fallbackModel: "backup", baseChatFn });
    await expect(fn([], { model: "primary" })).rejects.toThrow(
